const http = require('http');

const options = {
  hostname: 'localhost',
  port: 5001,
  path: '/api/quizzes/instructor',
  method: 'GET',
  headers: {
    'Content-Type': 'application/json'
  }
};

const req = http.request(options, (res) => {
  let data = '';
  
  res.on('data', (chunk) => {
    data += chunk;
  });
  
  res.on('end', () => {
    try {
      const quizzes = JSON.parse(data);
      console.log('Response status:', res.statusCode);
      console.log('Quizzes:', Array.isArray(quizzes) ? quizzes.length : 'Not an array');
      if (Array.isArray(quizzes)) {
        quizzes.forEach((quiz, index) => {
          console.log(`Quiz ${index + 1}: ${quiz.title}`);
          console.log(`Questions: ${quiz.questions ? quiz.questions.length : 0}`);
          console.log(`Source: ${quiz.source}`);
          console.log('---');
        });
      } else {
        console.log('Response:', data);
      }
    } catch (error) {
      console.error('Error parsing JSON:', error.message);
      console.log('Raw response:', data);
    }
  });
});

req.on('error', (e) => {
  console.error(`Problem with request: ${e.message}`);
});

req.end();
